import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

import { repoRoot as defaultRepoRoot, runCommand } from "./command-runner.mjs";

export const SCHEMA_SNAPSHOT_RELATIVE_PATH = "infra/supabase/schema.current.sql";

const DEFAULT_LOCAL_DATABASE_URL = "postgresql://postgres:postgres@127.0.0.1:54322/postgres";
const HEADER = [
  "-- Generated by `node scripts/development/dump-db-schema.mjs` against local Supabase (`infra/supabase/migrations`).",
  "-- Do not edit manually; add a migration and re-run `npm run ops -- run api.db-types`.",
].join("\n");

const DECLARED_PUBLIC_FUNCTION_PATTERN = /^CREATE (?:OR REPLACE )?FUNCTION "public"\."([^"]+)"/gmu;
const PUBLIC_FUNCTION_ACL_PATTERN = /^(?:GRANT|REVOKE)\b.*\bON FUNCTION "public"\."([^"]+)"/u;

export function formatSchemaSnapshot(rawSql) {
  const normalized = rawSql.replaceAll("\r\n", "\n");
  const declaredPublicFunctions = new Set(
    Array.from(normalized.matchAll(DECLARED_PUBLIC_FUNCTION_PATTERN), (match) => match[1]),
  );

  const filteredLines = normalized.split("\n").filter((line) => {
    const aclMatch = PUBLIC_FUNCTION_ACL_PATTERN.exec(line);
    if (!aclMatch) return true;
    return declaredPublicFunctions.has(aclMatch[1]);
  });

  const body = filteredLines.join("\n").replaceAll(/\n{3,}/g, "\n\n").trim();
  return `${HEADER}\n\n${body}\n`;
}

export async function dumpDbSchema({
  repoRoot = defaultRepoRoot,
  databaseUrl = process.env.TEST_DATABASE_URL ?? DEFAULT_LOCAL_DATABASE_URL,
} = {}) {
  const outputPath = path.join(repoRoot, SCHEMA_SNAPSHOT_RELATIVE_PATH);
  const effectiveDatabaseUrl = databaseUrl || DEFAULT_LOCAL_DATABASE_URL;

  await runCommand(
    "npx",
    [
      "--yes",
      "supabase@2.110.0",
      "db",
      "dump",
      "--db-url",
      effectiveDatabaseUrl,
      "--file",
      SCHEMA_SNAPSHOT_RELATIVE_PATH,
    ],
    { cwd: repoRoot },
  );

  const formatted = formatSchemaSnapshot(await readFile(outputPath, "utf8"));
  await writeFile(outputPath, formatted, "utf8");
  return outputPath;
}

const isEntrypoint =
  process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);

if (isEntrypoint) {
  dumpDbSchema().catch((error) => {
    console.error(`[dump-db-schema] ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 1;
  });
}
